"""Dependency-free local Chat preview assets. Never embed credentials or production endpoints."""

CHAT_HTML = """<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>DSH 检索需求体验</title><link rel="stylesheet" href="/chat.css"></head>
<body><main>
  <header><div><span class="eyebrow">LOCAL PREVIEW</span><h1>检索需求 Chat</h1></div><div class="project">项目 <strong>demo</strong> / 子维度 <strong>default</strong></div></header>
  <div class="layout"><aside class="history"><div class="history-title"><h2>历史记录</h2><button class="icon-button" id="refresh-history" aria-label="刷新历史记录">↻</button></div><p>草稿会话与正式版本分层保存；会话不是业务执行时间线。</p><div id="history-list"></div></aside>
  <div class="chat"><section class="notice">本页使用模拟身份和本地账本。反馈会生成新的需求版本，但文字尚未编译成真实清洗规则，也不会启动真实检索。</section>
    <section id="timeline" class="timeline" aria-live="polite"><article class="message system"><h2>新建数据需求</h2><p>描述你想要的数据，系统会先生成完整确认卡，不会直接执行。</p></article></section>
    <section class="composer" id="new-request"><label for="request-text">需求描述</label><textarea id="request-text" rows="4" placeholder="例如：找一批清晰的客厅图片，不要水印"></textarea><div class="row"><label for="target-count">目标数量</label><input id="target-count" type="number" min="1" max="10000" value="10"><button id="prepare-task">生成确认卡</button></div></section>
    <section class="composer hidden" id="feedback-box"><label for="feedback-text">继续反馈</label><textarea id="feedback-text" rows="3" placeholder="例如：再去掉所有包含文字的图片"></textarea><div class="actions"><button id="prepare-feedback">生成反馈确认卡</button><button class="secondary" id="new-task">新建另一单</button></div></section>
    <p id="status" role="status"></p>
  </div></div>
</main><script src="/chat.js"></script></body></html>"""

CHAT_CSS = """
:root{font-family:Inter,"PingFang SC",system-ui,sans-serif;color:#17201d;background:#eef2ed}*{box-sizing:border-box}
body{margin:0;background:radial-gradient(circle at 20% 0,#d8e8dc,transparent 42%),#eef2ed}main{max-width:920px;margin:auto;min-height:100vh;padding:40px 22px 80px}
header{display:flex;justify-content:space-between;gap:24px;align-items:end;margin-bottom:22px}h1{margin:4px 0 0;font:700 36px/1.1 Georgia,serif}.eyebrow{font-size:12px;letter-spacing:.16em;color:#42755c}.project{background:#fff8;border:1px solid #cad6cc;border-radius:999px;padding:10px 16px}
.layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:18px;align-items:start}.history{position:sticky;top:18px;background:#fffffff0;border:1px solid #cbd8ce;border-radius:18px;padding:14px}.history-title{display:flex;align-items:center;justify-content:space-between}.history h2{font-size:18px;margin:0}.history>p{font-size:12px;color:#66736b}.history-section{font-size:12px;font-weight:700;letter-spacing:.08em;color:#4e6659;margin-top:14px}.icon-button{padding:6px 10px;background:#e2eae4;color:#274636}.history-item{display:block;width:100%;text-align:left;background:white;color:#263c31;border:1px solid #d4ddd5;margin-top:8px;padding:10px}.history-item.active{border-color:#347b55;background:#e9f4ec}.history-item small{display:block;color:#68756d;margin-top:5px}.empty{font-size:13px;color:#68756d;padding:10px 2px}.chat{min-width:0}
.notice{background:#fff8e6;border:1px solid #e2c478;border-radius:14px;padding:13px 16px;color:#6a541b}.timeline{display:grid;gap:14px;margin:22px 0}.message{max-width:82%;padding:16px 18px;border-radius:18px;background:white;box-shadow:0 8px 26px #33483b12}.message.user{justify-self:end;background:#214e3a;color:white}.message h2{font-size:16px;margin:0 0 8px}.message p{margin:0;white-space:pre-wrap}.card{border-left:4px solid #55a579}.card dl{display:grid;grid-template-columns:130px 1fr;gap:8px;margin:12px 0}.card dt{color:#65736b}.card dd{margin:0;word-break:break-word}.actions{display:flex;gap:8px;margin-top:14px}
.composer{background:#fffffff0;border:1px solid #cbd8ce;border-radius:18px;padding:18px;display:grid;gap:10px}.row{display:flex;gap:12px;align-items:center}.row input{width:100px}textarea,input{font:inherit;border:1px solid #b8c8bb;border-radius:10px;padding:11px;background:white}textarea{resize:vertical;width:100%}button{font:600 14px inherit;border:0;border-radius:10px;padding:11px 16px;background:#245d43;color:white;cursor:pointer}button.secondary{background:#e2eae4;color:#274636}button:disabled{opacity:.55;cursor:wait}.hidden{display:none!important}#status{color:#8b3c2f;min-height:1.4em}pre{white-space:pre-wrap;font-size:12px;background:#f4f6f3;padding:10px;border-radius:8px}@media(max-width:760px){header{align-items:start;flex-direction:column}.layout{grid-template-columns:1fr}.history{position:static}.message{max-width:100%}.row{align-items:stretch;flex-direction:column}.row input{width:100%}}
"""

CHAT_JS = r"""
const state={task:null,draft:null,feedback:null,conversationId:null};
const headers={'Content-Type':'application/json','X-Tenant-Id':'tenant-a','X-User-Id':'user-a'};
const $=id=>document.getElementById(id); const timeline=$('timeline');
const key=prefix=>prefix+'-'+crypto.randomUUID();
async function api(path,{method='GET',body,keyValue}={}){const h={...headers};if(keyValue)h['Idempotency-Key']=keyValue;const r=await fetch(path,{method,headers:h,body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw new Error(`${data.code||r.status}: ${data.message||'请求失败'}`);return data}
function message(kind,title,text){const a=document.createElement('article');a.className='message '+kind;const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=text;a.append(h,p);timeline.append(a);a.scrollIntoView({behavior:'smooth',block:'end'});return a}
function card(title,rows,actions=[]){const a=document.createElement('article');a.className='message card';const h=document.createElement('h2');h.textContent=title;a.append(h);const dl=document.createElement('dl');for(const [name,value] of rows){const dt=document.createElement('dt');dt.textContent=name;const dd=document.createElement('dd');dd.textContent=String(value);dl.append(dt,dd)}a.append(dl);if(actions.length){const box=document.createElement('div');box.className='actions';for(const [label,fn,secondary] of actions){const b=document.createElement('button');b.textContent=label;if(secondary)b.className='secondary';b.addEventListener('click',fn);box.append(b)}a.append(box)}timeline.append(a);a.scrollIntoView({behavior:'smooth',block:'end'});return a}
function draftBody(text,count){return{dimension_id:'default',query_spec:{schema_version:'query-spec@2',raw_request:text,media_type:'image',target_count:count,business_domain:'local_preview',intra_batch_dedup:{policy_ref:'exact-content',config_version:'1'},cross_batch_dedup:{scope:'none',references:[],comparison_methods:[],reference_digest:null},refill_policy:{mode:'input_only',target_count:count,approved_library_ids:[],progression:'manual'}},node_modes:{expansion:'manual',retrieval:'manual',cleaning:'manual',refill:'manual',packaging:'manual'}}}
function setBusy(v){document.querySelectorAll('button').forEach(b=>b.disabled=v);$('status').textContent=v?'处理中…':''}
function resetTimeline(title='新建数据需求',text='描述你想要的数据，系统会先生成完整确认卡，不会直接执行。'){timeline.replaceChildren();message('system',title,text)}
async function refreshHistory(){const box=$('history-list');try{const [conversations,tasks]=await Promise.all([api('/v1/retrieval/projects/demo/conversations'),api('/v1/retrieval/projects/demo/tasks')]);box.replaceChildren();const section=label=>{const h=document.createElement('div');h.className='history-section';h.textContent=label;box.append(h)};section('草稿会话');if(!conversations.items.length){const p=document.createElement('p');p.className='empty';p.textContent='暂无已记录会话；旧账本无法补回此前聊天';box.append(p)}for(const item of conversations.items){const b=document.createElement('button');b.className='history-item'+(state.conversationId===item.conversation_id?' active':'');const title=document.createElement('span');title.textContent=`会话 · ${item.message_count} 条输入`;const meta=document.createElement('small');meta.textContent=`${item.confirmation_count} 次正式确认 · ${item.last_message_at||'无时间'}`;b.append(title,meta);b.addEventListener('click',()=>openConversation(item.conversation_id));box.append(b)}section('正式需求');if(!tasks.items.length){const p=document.createElement('p');p.className='empty';p.textContent='还没有已确认的正式需求';box.append(p)}for(const item of tasks.items){const b=document.createElement('button');b.className='history-item'+(state.task&&state.task.task_id===item.task_id?' active':'');b.dataset.taskId=item.task_id;const title=document.createElement('span');title.textContent=item.raw_request;const meta=document.createElement('small');meta.textContent=`revision ${item.confirmed_revision} · ${item.run_status}${item.pending_draft?' · 有待确认反馈':''}`;b.append(title,meta);b.addEventListener('click',()=>openTask(item.task_id));box.append(b)}}catch(e){box.replaceChildren();const p=document.createElement('p');p.className='empty';p.textContent='历史记录加载失败：'+e.message;box.append(p)}}
async function openConversation(conversationId){setBusy(true);try{const data=await api(`/v1/retrieval/conversations/${conversationId}`);state.conversationId=conversationId;state.task=null;resetTimeline('草稿会话',`会话 ${conversationId}\n以下是独立会话记录，不是业务执行时间线。`);for(const item of data.messages){message('user',item.kind==='feedback'?'追加反馈':'需求输入',item.text)}for(const item of data.confirmations){card(`方案已确认 · revision ${item.revision}`,[['任务',item.task_id],['草稿',item.draft_id],['确认时间',item.confirmed_at]],[['查看正式版本',()=>openTask(item.task_id),false]])}$('new-request').classList.add('hidden');$('feedback-box').classList.add('hidden');await refreshHistory()}catch(e){$('status').textContent=e.message}finally{setBusy(false)}}
function showProgress(progress){card('五节点进度',[['绑定',`revision ${progress.revision} · generation ${progress.run_generation}`],['当前阶段',progress.stage||progress.run_status],['目标',progress.counts.target],['有效数量',progress.counts.accepted===null?'未知':progress.counts.accepted],['缺口',progress.counts.gap===null?'未知':progress.counts.gap]]);for(const node of progress.nodes){card(node.label,[['执行状态',node.node_status],['推进门禁',node.gate_status],['模式',node.mode],['说明',node.detail]])}message('system','计数说明',progress.note)}
async function openTask(taskId){setBusy(true);try{const [task,revisions,progress]=await Promise.all([api(`/v1/retrieval/tasks/${taskId}`),api(`/v1/retrieval/tasks/${taskId}/revisions`),api(`/v1/retrieval/tasks/${taskId}/progress`)]);state.task=task;localStorage.setItem('dsh-task-id',taskId);resetTimeline('历史需求',`任务 ${taskId}\n正式版本 ${task.confirmed_revision} · 状态 ${task.run_status}`);showProgress(progress);for(const revision of revisions.items){card(`正式版本 ${revision.revision}`,[['需求',revision.proposal.query_spec.raw_request],['方案摘要',revision.proposal_digest]])}if(task.pending_draft){state.feedback=task.pending_draft;card('待确认的反馈草稿',[['基于版本',state.feedback.base_revision],['反馈内容',state.feedback.feedback_text],['执行说明',state.feedback.execution_note]],[["确认新版本",()=>decideFeedback('confirm'),false],["拒绝草稿",()=>decideFeedback('reject'),true]])}$('new-request').classList.add('hidden');$('feedback-box').classList.remove('hidden');await refreshHistory();return true}catch(e){$('status').textContent=e.message;return false}finally{setBusy(false)}}
async function prepareTask(){const text=$('request-text').value.trim(),count=Number($('target-count').value);if(!text||!Number.isInteger(count)||count<1){$('status').textContent='请填写需求和正整数数量';return}setBusy(true);try{message('user','你的需求',text);state.draft=await api('/v1/retrieval/projects/demo/drafts',{method:'POST',keyValue:key('draft'),body:draftBody(text,count)});card('提交确认卡',[['项目','demo / default'],['目标',text],['数量',count+' 张图片'],['去重','本批 exact-content'],['补数','input_only / 手动'],['节点','五节点手动']],[["确认提单",confirmTask,false]]);$('new-request').classList.add('hidden')}catch(e){$('status').textContent=e.message}finally{setBusy(false)}}
async function confirmTask(){setBusy(true);try{state.task=await api('/v1/retrieval/tasks',{method:'POST',keyValue:key('task'),body:{draft_id:state.draft.draft_id,expected_draft_version:state.draft.draft_version,proposal_digest:state.draft.proposal_digest,action:'confirm'}});localStorage.setItem('dsh-task-id',state.task.task_id);message('system','提单成功',`任务 ${state.task.task_id}\n正式版本 ${state.task.confirmed_revision} · 状态 ${state.task.run_status}`);$('feedback-box').classList.remove('hidden');await refreshHistory()}catch(e){$('status').textContent=e.message}finally{setBusy(false)}}
async function prepareFeedback(){const text=$('feedback-text').value.trim();if(!text){$('status').textContent='请填写反馈';return}setBusy(true);try{message('user','追加反馈',text);state.feedback=await api(`/v1/retrieval/tasks/${state.task.task_id}/feedback`,{method:'POST',keyValue:key('feedback'),body:{text,scope:'all',expected_revision:state.task.confirmed_revision,expected_task_version:state.task.task_version}});card('反馈确认卡',[['基于版本',state.feedback.base_revision],['反馈范围','全部'],['反馈内容',state.feedback.feedback_text],['完整需求',state.feedback.proposal.query_spec.raw_request],['执行说明',state.feedback.execution_note]],[["确认新版本",()=>decideFeedback('confirm'),false],["拒绝草稿",()=>decideFeedback('reject'),true]]);$('feedback-box').classList.add('hidden')}catch(e){$('status').textContent=e.message}finally{setBusy(false)}}
async function decideFeedback(action){setBusy(true);try{const result=await api(`/v1/retrieval/tasks/${state.task.task_id}/confirmations`,{method:'POST',keyValue:key(action),body:{draft_id:state.feedback.draft_id,expected_draft_version:state.feedback.draft_version,proposal_digest:state.feedback.proposal_digest,expected_task_version:state.feedback.base_task_version,action}});state.task=result.task;message('system',action==='confirm'?'新版本已确认':'反馈草稿已拒绝',action==='confirm'?`正式版本 ${state.task.confirmed_revision} · generation ${state.task.run_generation}\n反馈文字已保存，但尚未编译为真实清洗规则。`:'原正式版本和运行保持不变。');$('feedback-text').value='';$('feedback-box').classList.remove('hidden');await refreshHistory()}catch(e){$('status').textContent=e.message}finally{setBusy(false)}}
$('prepare-task').addEventListener('click',prepareTask);$('prepare-feedback').addEventListener('click',prepareFeedback);$('new-task').addEventListener('click',()=>{localStorage.removeItem('dsh-task-id');location.reload()});$('refresh-history').addEventListener('click',refreshHistory);
(async function initialize(){await refreshHistory();const taskId=localStorage.getItem('dsh-task-id');if(taskId&&!await openTask(taskId))localStorage.removeItem('dsh-task-id')})();
"""
